import pandas as pd
import json
from helper import load_fees, volume_bucket

# Load the fees data
fees = load_fees()

# First, let's understand the monthly_volume field structure
print("Sample fees records with monthly_volume:")
for i, fee in enumerate(fees[:10]):
    print(f"Fee {fee['ID']}: monthly_volume = {fee['monthly_volume']}")

# Get unique monthly_volume values
volume_values = set()
for fee in fees:
    vol = fee['monthly_volume']
    if vol is not None:
        if isinstance(vol, list):
            for v in vol:
                volume_values.add(v)
        else:
            volume_values.add(vol)

print(f"\nUnique monthly_volume values in fees: {sorted(volume_values)}")
